// Generated by scripts/build-arcade-games.mjs. Edit source/ instead.
// Simulate at 60Hz on both ordinary and high-refresh displays. Keep rendering
// at native refresh rate, but discard long stalls instead of teleporting players.
function createNeonClock() {
    const step = 1000 / 60;
    let previous = null;
    let accumulator = 0;
    return {
        reset() { previous = null; accumulator = 0; },
        advance(timestamp, updateStep, isActive) {
            if (!Number.isFinite(timestamp)) return;
            if (previous === null) { previous = timestamp; return; }
            accumulator += Math.min(100, Math.max(0, timestamp - previous));
            previous = timestamp;
            let steps = 0;
            while (accumulator + 0.00001 >= step && steps < 5 && isActive()) {
                accumulator -= step;
                updateStep();
                steps++;
            }
            if (steps === 5) accumulator = Math.min(accumulator, step);
        }
    };
}
const neonClock = createNeonClock();



function playSlopSound(type) {
    if (!audioCtx) return;
    try {
        const now = audioCtx.currentTime;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.connect(gain);
        gain.connect(audioCtx.destination);

        switch (type) {
            case 'catch':
                osc.type = 'sine';
                osc.frequency.setValueAtTime(440, now);
                osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
                gain.gain.setValueAtTime(0.15, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.12);
                osc.start(now);
                osc.stop(now + 0.12);
                break;
            case 'feed':
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(300, now);
                osc.frequency.exponentialRampToValueAtTime(600, now + 0.08);
                osc.frequency.exponentialRampToValueAtTime(900, now + 0.16);
                gain.gain.setValueAtTime(0.18, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
                osc.start(now);
                osc.stop(now + 0.2);
                break;
            case 'hazard':
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(200, now);
                osc.frequency.linearRampToValueAtTime(70, now + 0.25);
                gain.gain.setValueAtTime(0.2, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);
                osc.start(now);
                osc.stop(now + 0.25);
                break;
            case 'throw':
                osc.type = 'sine';
                osc.frequency.setValueAtTime(600, now);
                osc.frequency.exponentialRampToValueAtTime(300, now + 0.08);
                gain.gain.setValueAtTime(0.1, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);
                osc.start(now);
                osc.stop(now + 0.08);
                break;
            case 'gameover':
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(350, now);
                osc.frequency.exponentialRampToValueAtTime(60, now + 0.6);
                gain.gain.setValueAtTime(0.25, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.65);
                osc.start(now);
                osc.stop(now + 0.65);
                break;
        }
    } catch (e) {}
}

